import json,pathlib
out=pathlib.Path('docs/rtl-migration-visual-history');m=json.loads((out/'manifest.json').read_text());c=json.loads((out/'comparisons/manifest.json').read_text());data=json.dumps({'manifest':m,'comparisons':c},ensure_ascii=False).replace('<','\\u003c')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enterprise RTL — Visual History</title>
<style>:root{color-scheme:dark;--bg:#09121f;--panel:#142238;--ink:#eaf0fa;--muted:#a6b7cf;--accent:#d3dc95}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,sans-serif}a{color:var(--accent)}header,main,footer{max-width:1440px;margin:auto;padding:32px}header{padding-top:70px}h1{font-size:clamp(32px,5vw,64px);line-height:1.1;margin:14px 0}h2{font-size:30px;margin:0}h3{font-size:19px}.eyebrow,.badge{font-size:12px;letter-spacing:.04em;text-transform:uppercase;color:var(--accent)}.lead{max-width:900px;color:var(--muted);font-size:20px}nav{display:flex;gap:8px;flex-wrap:wrap;margin:28px 0}nav a,button{border:1px solid #43536a;border-radius:8px;padding:8px 12px;text-decoration:none;background:var(--panel);color:var(--ink);cursor:pointer}button[aria-pressed=true]{background:var(--accent);color:#101720}section{border-top:1px solid #33445e;padding:42px 0;scroll-margin-top:20px}.stage-head{display:flex;gap:20px;align-items:flex-start}.num{font-size:48px;font-weight:800;color:var(--accent);line-height:1}.ar{direction:rtl;text-align:right;font-size:19px;color:#d3deed}.commit{font:13px monospace;overflow-wrap:anywhere}.context{display:grid;grid-template-columns:1fr 1fr;gap:24px}.note{border-left:3px solid #d6ad74;padding:12px 18px;background:#251f23;color:#eddbcb;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(285px,1fr));gap:20px}.card{background:var(--panel);border:1px solid #31415b;border-radius:12px;overflow:hidden}.card img{width:100%;height:225px;object-fit:contain;background:#07101d;display:block}.copy{padding:16px}.copy p{margin:5px 0}.meta{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pair img{height:320px}.chips{display:flex;gap:10px;flex-wrap:wrap}.stat{background:var(--panel);padding:12px 18px;border-radius:9px}.stat strong{color:var(--accent)}.hidden{display:none}footer{color:var(--muted)}@media(max-width:700px){header,main,footer{padding:22px}.context,.pair{grid-template-columns:1fr}.stage-head{gap:12px}.num{font-size:34px}.card img{height:250px}}</style>
<header><div class="eyebrow">Enterprise RTL Migration Lab · Evidence atlas</div><h1>From LTR baseline<br>to verified RTL delivery.</h1><p class="lead">Twelve fixed stages. Original evidence stays original. Recreated screenshots and real report excerpts are explicitly labeled.</p><p class="ar">تاريخ الترحيل في 12 مرحلة بنفس ترتيب الخريطة. الصور الأصلية محفوظة، وأي لقطة مُعاد إنتاجها أو مقتطف تقرير متعلّم بوضوح.</p><div class="chips" id="stats"></div><nav id="nav" aria-label="Stage navigation"></nav><div class="chips" id="filters"><button aria-pressed="true" data-type="all">All evidence</button><button aria-pressed="false" data-type="historical-existing">Original historical</button><button aria-pressed="false" data-type="recreated">Recreated apps</button><button aria-pressed="false" data-type="report-evidence">Reports / source</button></div><p><a href="manifest.json">Machine-readable manifest</a> · <a href="README.md">Method and limitations</a> · <a href="#comparisons">Before / After</a></p><aside class="note">Static findings ≠ confirmed bugs. A test receipt is not a new test run. Final lab delivery does not certify deployment origins. Native date fields can differ with macOS regional preferences; no preference or baseline was changed for these captures.</aside></header><main id="stages"></main><main id="comparisons"><h2>Before / After — ownership and evidence</h2><p>Before: original Phase 2A. After: recreated representative Stage 09. These pairs are not a claim of a new pixel-diff test or capture at the exact fixing commit.</p><div id="pairs"></div></main><footer>No runtime, policy, scanner, snapshot or historical commit was changed. Open images for full resolution. Gallery works directly from disk and through a local static server; no network scripts, fonts or analytics.</footer>
<script id="data" type="application/json">__DATA__</script><script>
const {manifest:m,comparisons}=JSON.parse(document.getElementById('data').textContent);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.getElementById('stats').innerHTML=`<span class="stat"><strong>12</strong> stages</span><span class="stat"><strong>${m.counts.reused}</strong> original images reused</span><span class="stat"><strong>${m.counts.newlyCaptured}</strong> recreated app captures</span><span class="stat"><strong>${m.counts.reportCards}</strong> source/report cards</span>`;
document.getElementById('nav').innerHTML=m.stages.map(s=>`<a href="#stage-${s.stage}">${String(s.stage).padStart(2,'0')}</a>`).join('');
document.getElementById('stages').innerHTML=m.stages.map(s=>`<section id="stage-${s.stage}"><div class="stage-head"><div class="num">${String(s.stage).padStart(2,'0')}</div><div><h2>${esc(s.titleEn)}</h2><div class="ar" lang="ar">${esc(s.titleAr)}</div><p class="commit"><a href="${esc(s.commitUrl)}" target="_blank" rel="noopener">${esc(s.commit)}</a></p></div></div><p>${esc(s.summaryEn)}</p><p class="ar" lang="ar">${esc(s.summaryAr)}</p><div class="context"><div><h3>Before</h3><p>${esc(s.before)}</p></div><div><h3>Investigated / changed</h3><ul>${s.changes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div><aside class="note">${s.limitations.map(esc).join('<br>')}</aside><p><a href="stage-${String(s.stage).padStart(2,'0')}/README.md">Stage notes</a> · Status: ${esc(s.verificationStatus)}</p><div class="grid">${s.screenshots.map(x=>`<article class="card" data-evidence="${x.type}"><a href="${esc(x.path)}" target="_blank" rel="noopener"><img loading="lazy" src="${esc(x.path)}" alt="${esc(x.descriptionEn)}"></a><div class="copy"><span class="badge">${esc(x.type)}</span><p>${esc(x.descriptionEn)}</p><p class="ar" lang="ar">${esc(x.descriptionAr)}</p><p class="meta">${esc(x.sourceCommit.slice(0,12))}${x.viewport?' · '+x.viewport.width+'×'+x.viewport.height:''}${x.browserVersion?' · Chrome '+esc(x.browserVersion):''}</p>${x.sourceUrl?`<a href="${esc(x.sourceUrl)}">Exact source</a>`:''}</div></article>`).join('')}</div></section>`).join('');
document.getElementById('pairs').innerHTML=comparisons.map(x=>`<section><h3>${esc(x.issueId)} — ${esc(x.title)}</h3><p>${esc(x.rootCause)} → ${esc(x.fix)}</p><p><a href="${esc(x.commitUrl)}">Fixing commit ${x.fixingCommit.slice(0,12)}</a></p><div class="pair">${[['BEFORE · original Phase 2A',x.before],['AFTER · recreated Stage 09',x.after]].map(([label,src])=>`<article class="card"><a href="${esc(src)}" target="_blank" rel="noopener"><img loading="lazy" src="${esc(src)}" alt="${esc(label)}"></a><div class="copy">${esc(label)}</div></article>`).join('')}</div><p class="meta">${esc(x.verificationStatus)}. ${esc(x.limitations)}</p></section>`).join('');
document.getElementById('filters').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('#filters button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-evidence]').forEach(x=>x.classList.toggle('hidden',b.dataset.type!=='all'&&x.dataset.evidence!==b.dataset.type));});
</script></html>'''
(out/'index.html').write_text(page.replace('__DATA__',data))
